27	/**
28	 * PortOne API 클라이언트
29	 * 외부 결제 API와의 통신 담당
30	 */
31	@Service
32	@RequiredArgsConstructor
33	@Slf4j
34	public class PortOneApiClient {
35	
36	    private final RestTemplate restTemplate;
37	
38	    private static final String BASE_URL = "https://api.iamport.kr";
39	    private static final String TOKEN_URL = "/users/getToken";
40	    private static final String ONE_TIME_PAYMENT_URL = "/subscribe/payments/onetime";
41	    private static final String CANCEL_PAYMENT_URL = "/payments/cancel";
42	
43	    @Value("${imp.key}")
44	    private String impKey;
45	
46	    @Value("${imp.secret}")
47	    private String impSecret;
48	
