50	    private String pg; // PG 설정 값
51	
52	    @Value("${imp.storeId}")
53	    private String storeId;
54	
55	    @Value("${payment.api.timeout:10000}")
56	    private int apiTimeout; // API 호출 타임아웃 (밀리초)
57	
58	    @Value("${payment.retry.max-attempts:3}")
59	    private int maxRetryAttempts; // 최대 재시도 횟수
