142	    public String requestTestPayment(PaymentInfoCreateDto dto) {
143	        Instant start = Instant.now();
144	        String url = BASE_URL + ONE_TIME_PAYMENT_URL;
145	
146	        log.info("PortOne API 테스트 결제 요청 시작: 카드번호={}", PaymentCardUtils.maskCardNumberForLogging(dto.getCardNumber()));
147	
148	        // 입력값 검증
149	        PaymentCardUtils.validateCardInfo(dto);
150	
151	        String accessToken;
152	        try {
153	            accessToken = getAccessToken(); // 인증 토큰 발급
154	        } catch (PaymentException e) {
155	            log.error("테스트 결제 요청 중 토큰 발급 실패: {}", e.getMessage());
156	            throw e; // 토큰 발급 실패 예외 전파
157	        }
158	
159	        Map<String, Object> requestBody = new HashMap<>();
160	        requestBody.put("pg", "nice");
161	        requestBody.put("merchant_uid", UUID.randomUUID().toString());
162	        requestBody.put("method", "card"); // 결제 방식
163	        requestBody.put("currency", "KRW"); // 결제 통화 설정
164	        requestBody.put("amount", 100);
165	        requestBody.put("card_number", dto.getCardNumber());
166	        requestBody.put("expiry", dto.getExpirationDate());
167	        requestBody.put("birth", dto.getBirthDate());
168	        requestBody.put("pwd_2digit", dto.getCardPassword());
169	
170	        HttpHeaders headers = new HttpHeaders();
171	        headers.set("Authorization", "Bearer "+ accessToken); // 인증 토큰 포함
172	        headers.setContentType(MediaType.APPLICATION_JSON);
173	
174	        try {
175	            // JSON 직렬화
176	            ObjectMapper objectMapper = new ObjectMapper();
177	            String jsonBody = objectMapper.writeValueAsString(requestBody);
178	
179	            // 디버깅 로그
180	            log.debug("PortOne API 테스트 결제 요청 정보: URL={}, Headers={}", url, headers);
181	
182	            HttpEntity<String> requestEntity = new HttpEntity<>(jsonBody, headers);
183	
184	            ResponseEntity<Map> response = restTemplate.exchange(url, HttpMethod.POST, requestEntity, Map.class);
185	
186	            // 응답 상태와 내용 로그 출력
187	            log.debug("PortOne API 테스트 결제 응답: 상태코드={}", response.getStatusCodeValue());
188	
189	            if (response.getStatusCode() != HttpStatus.OK || !response.getBody().get("code").equals(0)) {
190	                String errorMessage = "결제 요청 실패: " +
191	                        (response.getBody().containsKey("message") ? response.getBody().get("message") : "알 수 없는 오류");
192	                log.error("PortOne API 테스트 결제 요청 실패: {}", errorMessage);
193	                throw new PaymentProcessingException(errorMessage);
194	            }
195	
196	            Map<String, Object> paymentResponse = (Map<String, Object>) response.getBody().get("response");
197	            String impUid = (String) paymentResponse.get("imp_uid");
198	            log.info("PortOne API 테스트 결제 성공: impUid={}", impUid);
199	
200	            // 처리 시간 로깅
201	            Instant end = Instant.now();
202	            Duration duration = Duration.between(start, end);
203	            log.debug("PortOne API 테스트 결제 처리 시간: {}ms", duration.toMillis());
204	
205	            return impUid;
206	        } catch (PaymentException e) {
207	            throw e; // 이미 PaymentException이면 그대로 전파
208	        } catch (RestClientException e) {
209	            log.error("PortOne API 통신 중 오류 발생: {}", e.getMessage(), e);
210	            throw new PaymentApiException("결제 서비스 API 통신 중 오류가 발생했습니다.", e);
211	        } catch (Exception e) {
212	            log.error("PortOne API 테스트 결제 요청 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
213	            throw new PaymentProcessingException("테스트 결제 처리 중 오류가 발생했습니다.", e);
214	        }
215	    }
