217	    /**
218	     * 카드 결제 처리
219	     * @param paymentInfo 결제 정보 엔티티
220	     * @param amount 결제 금액
221	     * @return 결제 응답 정보 맵
222	     * @throws PaymentProcessingException 결제 처리 실패 시
223	     */
224	    @Retryable(
225	            value = {PaymentApiException.class},
226	            maxAttempts = 3,
227	            backoff = @Backoff(delay = 1000)
