229	    public Map<String, Object> processCardPayment(PaymentInfo paymentInfo, double amount) {
230	        Instant start = Instant.now();
231	        String url = BASE_URL + ONE_TIME_PAYMENT_URL;
232	
233	        log.info("PortOne API 카드 결제 요청 시작: 금액={}", amount);
234	
235	        // 입력값 검증
236	        validatePaymentInfo(paymentInfo, amount);
237	
238	        String accessToken;
239	        try {
240	            accessToken = getAccessToken();
241	        } catch (PaymentException e) {
242	            log.error("카드 결제 요청 중 토큰 발급 실패: {}", e.getMessage());
243	            throw e; // 토큰 발급 실패 예외 전파
