250	        requestBody.put("amount", amount);
251	        requestBody.put("currency", "KRW"); // 결제 통화 설정
252	        requestBody.put("card_number", paymentInfo.getCardNumber());
253	        requestBody.put("expiry", paymentInfo.getExpirationDate());
254	        requestBody.put("birth", paymentInfo.getBirthDate());
255	        requestBody.put("pwd_2digit", paymentInfo.getCardPassword());
256	
257	        HttpHeaders headers = new HttpHeaders();
258	        headers.set("Authorization", "Bearer " + accessToken);
259	        headers.setContentType(MediaType.APPLICATION_JSON);
260	
261	        try {
262	            ObjectMapper objectMapper = new ObjectMapper();
263	            String jsonBody = objectMapper.writeValueAsString(requestBody);
264	
265	            HttpEntity<String> requestEntity = new HttpEntity<>(jsonBody, headers);
266	            ResponseEntity<Map> response = restTemplate.exchange(url, HttpMethod.POST, requestEntity, Map.class);
267	
268	            log.debug("PortOne API 카드 결제 응답: 상태코드={}", response.getStatusCodeValue());
269	
270	            if (response.getStatusCode() != HttpStatus.OK || !response.getBody().get("code").equals(0)) {
271	                String errorMessage = "카드 결제 요청 실패: " +
272	                        (response.getBody().containsKey("message") ? response.getBody().get("message") : "알 수 없는 오류");
273	                log.error("PortOne API 카드 결제 요청 실패: {}", errorMessage);
274	                throw new PaymentProcessingException(errorMessage);
275	            }
276	
277	            Map<String, Object> paymentResponse = (Map<String, Object>) response.getBody().get("response");
278	            log.info("PortOne API 카드 결제 성공: impUid={}", paymentResponse.get("imp_uid"));
279	
280	            // 처리 시간 로깅
281	            Instant end = Instant.now();
282	            Duration duration = Duration.between(start, end);
283	            log.debug("PortOne API 카드 결제 처리 시간: {}ms", duration.toMillis());
284	
285	            return paymentResponse;
286	        } catch (PaymentException e) {
287	            throw e; // 이미 PaymentException이면 그대로 전파
288	        } catch (RestClientException e) {
289	            log.error("PortOne API 통신 중 오류 발생: {}", e.getMessage(), e);
290	            throw new PaymentApiException("결제 서비스 API 통신 중 오류가 발생했습니다.", e);
291	        } catch (Exception e) {
292	            log.error("PortOne API 카드 결제 요청 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
293	            throw new PaymentProcessingException("카드 결제 처리 중 오류가 발생했습니다.", e);
294	        }
295	    }
