369	    /**
370	     * 테스트 결제 환불
371	     * @param impUid 환불할 결제 고유 ID
372	     * @return 환불 성공 여부
373	     */
374	    public boolean cancelTestPayment(String impUid) {
375	        log.info("테스트 결제 환불 요청 시작: impUid={}", impUid);
376	        return refundPayment(impUid); // 환불 메서드 재사용
377	    }
378	
379	    /**
380	     * 결제 취소 (환불과 동일)
381	     * @param impUid 취소할 결제 고유 ID
382	     * @return 취소 성공 여부
383	     */
384	    public boolean cancelPayment(String impUid) {
385	        log.info("결제 취소 요청 시작: impUid={}", impUid);
386	        return refundPayment(impUid); // 환불 메서드 재사용
387	    }
