389	    /**
390	     * 카드번호 마스킹 메서드
391	     * @param cardNumber 원본 카드번호
392	     * @return 마스킹된 카드번호
393	     */
394	    private String maskCardNumber(String cardNumber) {
395	        return PaymentCardUtils.maskCardNumber(cardNumber);
396	    }
