398	    /**
399	     * 결제 정보 검증 메서드
400	     * @param paymentInfo 검증할 결제 정보
401	     * @param amount 결제 금액
402	     * @throws PaymentException 검증 실패 시
403	     */
404	    private void validatePaymentInfo(PaymentInfo paymentInfo, double amount) {
405	        if (paymentInfo == null) {
406	            throw new PaymentException(PaymentErrorCode.INVALID_CARD_INFO, "결제 수단 정보가 없습니다.");
407	        }
408	
409	        if (paymentInfo.getCardNumber() == null || paymentInfo.getCardNumber().isBlank()) {
410	            throw new PaymentException(PaymentErrorCode.INVALID_CARD_INFO, "카드 번호는 필수 입력 값입니다.");
411	        }
412	
413	        if (paymentInfo.getExpirationDate() == null || paymentInfo.getExpirationDate().isBlank()) {
414	            throw new PaymentException(PaymentErrorCode.INVALID_CARD_INFO, "카드 유효기간은 필수 입력 값입니다.");
415	        }
416	
417	        if (paymentInfo.getBirthDate() == null || paymentInfo.getBirthDate().isBlank()) {
418	            throw new PaymentException(PaymentErrorCode.INVALID_CARD_INFO, "생년월일은 필수 입력 값입니다.");
419	        }
420	
421	        if (paymentInfo.getCardPassword() == null || paymentInfo.getCardPassword().isBlank()) {
422	            throw new PaymentException(PaymentErrorCode.INVALID_CARD_INFO, "카드 비밀번호 앞 2자리는 필수 입력 값입니다.");
423	        }
424	
425	        if (amount <= 0) {
426	            throw new PaymentException(PaymentErrorCode.INVALID_PAYMENT_AMOUNT, "결제 금액은 0보다 커야 합니다.");
427	        }
428	    }
429	}

